# filename: compute_purchase_price.py
import sqlite3
import re
from datetime import datetime

def read_policy_documents():
    """Step 1: Read both policy documents from the workspace"""
    policy_v1_path = "⟨workdir⟩"
    policy_v3_path = "⟨workdir⟩"

    with open(policy_v1_path, 'r') as f:
        policy_v1 = f.read()

    with open(policy_v3_path, 'r') as f:
        policy_v3 = f.read()

    return policy_v1, policy_v3

def determine_authoritative_policy(policy_v1, policy_v3):
    """Step 2: Decide which one is the current authoritative policy"""

    # Strategy 1: Check version numbers in content
    v1_version_match = re.search(r'version\s*[:=]?\s*(\d+\.\d+)', policy_v1, re.IGNORECASE)
    v3_version_match = re.search(r'version\s*[:=]?\s*(\d+\.\d+)', policy_v3, re.IGNORECASE)

    # Strategy 2: Look for dates
    date_pattern = r'\b(\d{1,2}[-/]\d{1,2}[-/]\d{2,4}|\d{4}[-/]\d{1,2}[-/]\d{1,2})\b'
    v1_dates = re.findall(date_pattern, policy_v1)
    v3_dates = re.findall(date_pattern, policy_v3)

    # Strategy 3: Look for authoritative indicators
    authoritative_indicators = [
        'current', 'active', 'authoritative', 'effective', 
        'supersedes', 'replaces', 'latest', 'newest'
    ]

    deprecated_indicators = [
        'obsolete', 'deprecated', 'superseded', 'replaced',
        'old', 'previous', 'legacy', 'outdated'
    ]

    v3_authoritative_score = 0
    v1_authoritative_score = 0

    # Check v3 for authoritative indicators
    for indicator in authoritative_indicators:
        if indicator in policy_v3.lower():
            v3_authoritative_score += 1

    # Check v1 for deprecated indicators
    for indicator in deprecated_indicators:
        if indicator in policy_v1.lower():
            v3_authoritative_score += 1

    # Check v1 for authoritative indicators
    for indicator in authoritative_indicators:
        if indicator in policy_v1.lower():
            v1_authoritative_score += 1

    # Check v3 for deprecated indicators  
    for indicator in deprecated_indicators:
        if indicator in policy_v3.lower():
            v1_authoritative_score += 1

    # Check if one policy references/supersedes the other
    if 'v1.0' in policy_v3.lower() and ('supersedes' in policy_v3.lower() or 'replaces' in policy_v3.lower()):
        v3_authoritative_score += 2

    if 'v3.2' in policy_v1.lower() and ('superseded' in policy_v1.lower() or 'replaced' in policy_v1.lower()):
        v3_authoritative_score += 2

    # Default: higher version number is more likely to be current
    # Compare version numbers from filenames
    v3_authoritative_score += 1  # v3.2 > v1.0

    # Decision
    if v3_authoritative_score >= v1_authoritative_score:
        return policy_v3, "v3.2"
    else:
        return policy_v1, "v1.0"

def parse_policy_rules(policy_text):
    """Parse the policy text to extract computation rules for Purchase Price (incl. tax)"""

    rules = {
        'column_name': None,
        'calculation': 'sum',  # default to sum
        'conditions': [],
        'currency': 'CNY'
    }

    # Look for column reference patterns
    column_patterns = [
        r'"Purchase Price\s*\(incl\.\s*tax\)"',
        r'Purchase\s*Price\s*\(incl\.\s*tax\)',
        r'purchase\s*price.*tax',
        r'column.*purchase.*price',
        r'field.*purchase.*price'
    ]

    for pattern in column_patterns:
        matches = re.findall(pattern, policy_text, re.IGNORECASE)
        if matches:
            # Try to extract column name from context
            for match in matches:
                if 'column' in match.lower() or 'field' in match.lower():
                    # Look for column name after "column" or before/after
                    context = policy_text[max(0, policy_text.lower().find(match.lower())-100): 
                                         min(len(policy_text), policy_text.lower().find(match.lower())+100)]

                    # Try to find quoted column names
                    quoted_matches = re.findall(r'["\']([^"\']+)["\']', context)
                    for quoted in quoted_matches:
                        if 'purchase' in quoted.lower() and 'price' in quoted.lower():
                            rules['column_name'] = quoted
                            break

                    # Try to find column names in backticks or brackets
                    if not rules['column_name']:
                        bracketed = re.findall(r'[`\[\(]([^`\]\)]+)[`\]\)]', context)
                        for bracket in bracketed:
                            if 'purchase' in bracket.lower() and 'price' in bracket.lower():
                                rules['column_name'] = bracket
                                break

            if not rules['column_name']:
                # Use a reasonable default based on common patterns
                rules['column_name'] = 'purchase_price_incl_tax'
            break

    # Look for calculation instructions
    if 'sum' in policy_text.lower() or 'total' in policy_text.lower() or 'add' in policy_text.lower():
        rules['calculation'] = 'sum'
    elif 'average' in policy_text.lower() or 'mean' in policy_text.lower():
        rules['calculation'] = 'avg'
    elif 'count' in policy_text.lower():
        rules['calculation'] = 'count'

    # Look for currency specification
    if 'CNY' in policy_text or 'RMB' in policy_text or 'yuan' in policy_text.lower():
        rules['currency'] = 'CNY'
    elif 'USD' in policy_text or 'dollar' in policy_text.lower():
        rules['currency'] = 'USD'

    return rules

def apply_policy_to_database(policy_rules):
    """Step 3: Connect to the database and apply the chosen policy"""

    conn = sqlite3.connect('./database.db')
    cursor = conn.cursor()

    # First, check if pricing_system table exists
    cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='pricing_system';")
    if not cursor.fetchone():
        print("ERROR: pricing_system table not found")
        conn.close()
        return None

    # Get column information
    cursor.execute("PRAGMA table_info(pricing_system);")
    columns = [col[1] for col in cursor.fetchall()]

    # Determine which column to use
    target_column = None

    # If policy specifies a column name, use it
    if policy_rules['column_name']:
        # Try exact match first
        if policy_rules['column_name'] in columns:
            target_column = policy_rules['column_name']
        else:
            # Try case-insensitive match
            for col in columns:
                if col.lower() == policy_rules['column_name'].lower():
                    target_column = col
                    break

            # Try partial match
            if not target_column:
                for col in columns:
                    if 'purchase' in col.lower() and 'price' in col.lower():
                        target_column = col
                        break

            # Try any price-related column
            if not target_column:
                for col in columns:
                    if 'price' in col.lower() or 'amount' in col.lower() or 'cost' in col.lower():
                        target_column = col
                        break

    # If still no column found, use first numeric column
    if not target_column:
        cursor.execute("PRAGMA table_info(pricing_system);")
        col_info = cursor.fetchall()
        for col in col_info:
            if 'INT' in col[2].upper() or 'REAL' in col[2].upper() or 'DECIMAL' in col[2].upper() or 'FLOAT' in col[2].upper():
                target_column = col[1]
                break

    if not target_column:
        print("ERROR: No suitable column found for purchase price calculation")
        conn.close()
        return None

    print(f"Using column '{target_column}' for purchase price calculation")

    # Apply the calculation
    try:
        if policy_rules['calculation'] == 'sum':
            query = f"SELECT SUM({target_column}) FROM pricing_system WHERE {target_column} IS NOT NULL;"
        elif policy_rules['calculation'] == 'avg':
            query = f"SELECT AVG({target_column}) FROM pricing_system WHERE {target_column} IS NOT NULL;"
        elif policy_rules['calculation'] == 'count':
            query = f"SELECT COUNT({target_column}) FROM pricing_system WHERE {target_column} IS NOT NULL;"
        else:
            query = f"SELECT SUM({target_column}) FROM pricing_system WHERE {target_column} IS NOT NULL;"

        cursor.execute(query)
        result = cursor.fetchone()
        total_value = result[0] if result[0] is not None else 0

        # Handle currency conversion if needed (simplified)
        if policy_rules['currency'] == 'CNY':
            # Already in CNY (based on problem statement)
            pass
        elif policy_rules['currency'] == 'USD':
            # Assuming conversion rate of 7.2 CNY per USD
            total_value = total_value * 7.2

        conn.close()
        return total_value

    except sqlite3.OperationalError as e:
        print(f"Query error: {e}")

        # Try alternative: get all values and compute in Python
        try:
            cursor.execute(f"SELECT {target_column} FROM pricing_system WHERE {target_column} IS NOT NULL;")
            rows = cursor.fetchall()
            values = [row[0] for row in rows if row[0] is not None]

            if policy_rules['calculation'] == 'sum':
                total_value = sum(values)
            elif policy_rules['calculation'] == 'avg':
                total_value = sum(values) / len(values) if values else 0
            elif policy_rules['calculation'] == 'count':
                total_value = len(values)
            else:
                total_value = sum(values)

            conn.close()
            return total_value

        except Exception as e2:
            print(f"Alternative calculation error: {e2}")
            conn.close()
            return None

def main():
    """Main function to execute all steps"""

    # Step 1: Read policy documents
    policy_v1, policy_v3 = read_policy_documents()

    # Step 2: Determine authoritative policy
    authoritative_policy, policy_version = determine_authoritative_policy(policy_v1, policy_v3)
    print(f"Authoritative policy: version {policy_version}")

    # Parse the authoritative policy to get computation rules
    policy_rules = parse_policy_rules(authoritative_policy)
    print(f"Policy rules: {policy_rules}")

    # Step 3: Apply policy to database and compute total
    total_purchase_price = apply_policy_to_database(policy_rules)

    # Step 4: Output final result
    if total_purchase_price is not None:
        # Format the result appropriately
        if isinstance(total_purchase_price, float):
            # Round to 2 decimal places for currency
            total_purchase_price = round(total_purchase_price, 2)

        print(f"Final answer: {total_purchase_price}")
    else:
        print("Final answer: 0")

if __name__ == "__main__":
    main()
